/** One curated adapter for sites with shared catalogs and overlapping room IDs. */
public final class SeriesSource {
 static final String NAME="玩球/看球/飞速/飞球";
 static final String[][] SITES={{"bszb","比赛","https://www.bszb453.com","https://apc.x4w3s3i3i8n7p2m6w0.cc","https://openim-php-api.qaek4a2wjx6bt.cc"},{"kqzb","看球","https://www.kqzb708.com","https://apc.n7z-1g7c2g2n8j6s0p1n2.vip","https://openim-php-api.qaek4a2wjx6bt.cc"},{"wqzb","玩球","https://m.wqzb6644.com","https://apc.z2f3v4o2s1u3z5k5i1.cc","https://openim-php-api.qaek4a2wjx6bt.cc"},{"fszb","飞速","https://www.fszb674.com","https://apc.fs1xbf88dbfhiogd.com","https://openim-php-api.q2n1w3g2y5v0w4l1.cc"},{"fqzb","飞球","https://www.fqzb173.com","https://apc.j8w1d1r1p4g4q6t.cc","https://openim-php-api.qaek4a2wjx6bt.cc"}};
 // Published website transport wrapper constants. This is not media encryption
 // or DRM; only anonymous, login_status=0, account_bind=0 qualities are requested.
 static final String SALT="yKBm0pKLdVcGbnu4XGon13TsyBdEsjj3WVAzszpoqjn3BNmovLgzvcRTxD1Wey7QQ10kcov0b8e9oBi7jAUR",KEY="j3Qpq3BWs6qUCctm",IV="b2mdEEYbW1qprFsg";
 static final String SESSION=UUID.randomUUID().toString().replace("-","");
 static String[] site(String id)throws IOException{for(String[] s:SITES)if(s[0].equals(id))return s;throw new IOException("未知站点");}
 static JSONObject data(String[] site,String path,boolean cache)throws Exception{JSONObject root=(JSONObject)HttpData.json(HttpData.get(site[3]+path,site[2]+"/",cache,Collections.singletonMap("platform",site[0])).body);if(root.optInt("code")!=200)throw new IOException(root.optString("message","接口异常"));return root.getJSONObject("data");}
 static final class Room {String[] site;JSONObject list,detail;LinkedHashSet<String> aliases=new LinkedHashSet<String>();Room(String[] s,JSONObject r){site=s;list=r;aliases.add(s[1]);}}
 static void mergeRoom(Map<String,Room> rooms,Room incoming){String key=incoming.site[4]+":"+incoming.list.optString("chatroom_id");Room existing=rooms.get(key);if(existing==null)rooms.put(key,incoming);else existing.aliases.addAll(incoming.aliases);}
 static String roomLabel(Room room){StringBuilder names=new StringBuilder();for(String alias:room.aliases){if(names.length()>0)names.append("/");names.append(alias);}return names.toString();}
 static List<Room> collect()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);ArrayList<Future<List<Room>>> futures=new ArrayList<Future<List<Room>>>();try{for(String[] s:SITES)futures.add(pool.submit(()->{JSONArray list=data(s,"/v1/recommend/match",true).getJSONArray("list");ArrayList<Room> out=new ArrayList<Room>();for(int i=0;i<list.length();i++){JSONObject row=list.getJSONObject(i);if(allowed(row))out.add(new Room(s,row));}return out;}));LinkedHashMap<String,Room> unique=new LinkedHashMap<String,Room>();Throwable firstFailure=null;int good=0;for(Future<List<Room>> future:futures)try{for(Room r:future.get(20,TimeUnit.SECONDS))mergeRoom(unique,r);good++;}catch(Exception failure){if(firstFailure==null)firstFailure=failure.getCause()==null?failure:failure.getCause();}if(good==0)throw new IOException("联合站点当前均不可用",firstFailure);return new ArrayList<Room>(unique.values());}finally{pool.shutdownNow();}}
 public static boolean allowed(JSONObject row){int sport=row.optInt("sport_id");return !row.optString("user_nickname").trim().isEmpty()&&!row.optString("room_title").matches(".*(回放|录播|重播).* ".trim())&&row.optInt("status")==2&&sport>0&&sport<100&& !SourceSafety.promotional(row.optString("room_title")+" "+row.optString("user_nickname"));}
 static JSONObject detail(Room room)throws Exception{return data(room.site,"/v1/room?room_id="+room.list.optString("chatroom_id")+"&sport_id="+room.list.optInt("sport_id")+"&match_id="+room.list.optString("match_id","0"),true);}
 static Feeds.Page fetch(String view,int page)throws Exception{List<Room> rooms=collect();LinkedHashMap<String,Feeds.Match> out=new LinkedHashMap<String,Feeds.Match>();Map<String,JSONObject> details=new HashMap<String,JSONObject>();for(Room room:rooms){JSONObject row=room.list;String roomId=row.optString("chatroom_id"),matchId=row.optString("match_id"),sport=row.optString("sport_id"),eventKey=sport+":"+matchId;String title=row.optString("room_title");JSONObject info=details.get(eventKey);if(info==null){try{info=detail(room).optJSONObject("match_info");}catch(Exception ignored){}if(info==null)info=new JSONObject();details.put(eventKey,info);}boolean linked=titleMatches(title,info);String id=linked?"match:"+eventKey:"room:"+room.site[4].hashCode()+":"+roomId;Feeds.Match m=out.get(id);if(m==null){m=MoreSources.match(NAME,id);m.title=title;m.sport=title.matches("(?i).*(CS2|CS欧洲|电竞|DOTA|LOL).*")?"esports":sport;m.status="live";m.room=roomId;m.estimated=!linked;m.cover=linked?Feeds.str(row,"match_screenshot_url","screenshot_url"):Feeds.str(row,"screenshot_url");if(linked){m.home=info.optString("home_name");m.away=info.optString("away_name");m.league=info.optString("alias_name");m.time=MoreSources.time(info.optLong("match_time"));m.eventState=LiveState.words(Feeds.str(info,"match_status_name","status_name","match_detail_status","status"));m.score=info.optString("home_score")+" : "+info.optString("away_score");}m.raw.put("rooms",new JSONArray());out.put(id,m);}m.raw.getJSONArray("rooms").put(new JSONObject().put("site",room.site[0]).put("id",roomId).put("sport",sport).put("match",matchId).put("name",roomLabel(room)+" · "+row.optString("user_nickname","线路")));}for(Feeds.Match m:out.values())MoreSources.pack(m);return MoreSources.page(new ArrayList<Feeds.Match>(out.values()),page);}
 public static boolean titleMatches(String title,JSONObject info){String home=info.optString("home_name"),away=info.optString("away_name");String t=title.toLowerCase(Locale.ROOT).replaceAll("\\s+","");return !home.isEmpty()&&!away.isEmpty()&&!title.contains("回放")&&t.contains(home.toLowerCase(Locale.ROOT).replaceAll("\\s+",""))&&t.contains(away.toLowerCase(Locale.ROOT).replaceAll("\\s+",""));}
 static ArrayList<Feeds.Line> lines(Feeds.Match m)throws Exception{JSONArray refs=m.raw.getJSONObject("extra").getJSONArray("rooms");ArrayList<Feeds.Line> lines=new ArrayList<Feeds.Line>();for(int i=0;i<refs.length();i++){JSONObject r=refs.getJSONObject(i);String[] s=site(r.getString("site"));for(String quality:new String[]{"gqzm","bqzm"}){Feeds.Line line=new Feeds.Line(r.getString("name")+" · "+(quality.equals("gqzm")?"高清":"标清"),r.getString("site")+":"+r.getString("id")+":"+quality,"");line.referer=s[2]+"/";lines.add(line);}}return lines;}
 public static boolean free(JSONObject quality){return quality.optInt("switch")==1&&quality.optInt("login_status",1)==0&&quality.optInt("account_bind",1)==0;}
 public static String signature(Map<String,String> form)throws Exception{StringBuilder value=new StringBuilder();for(String key:new TreeSet<String>(form.keySet()))value.append(key).append(form.get(key));value.append(SALT);byte[] digest=MessageDigest.getInstance("MD5").digest(value.toString().getBytes("UTF-8"));StringBuilder hex=new StringBuilder();for(byte b:digest)hex.append(String.format(Locale.US,"%02x",b&255));return hex.toString();}
 static String resolve(Feeds.Match match,Feeds.Line line)throws Exception{String[] ids=line.id.split(":");if(ids.length!=3)throw new IOException("线路编号无效");String[] site=site(ids[0]);JSONArray refs=match.raw.getJSONObject("extra").getJSONArray("rooms");JSONObject ref=null;for(int i=0;i<refs.length();i++){JSONObject row=refs.getJSONObject(i);if(row.optString("site").equals(ids[0])&&row.optString("id").equals(ids[1]))ref=row;}if(ref==null)throw new IOException("缺少当前赛事线路");JSONObject detail=data(site,"/v1/room?room_id="+ids[1]+"&sport_id="+ref.optString("sport")+"&match_id="+ref.optString("match"),false);if(detail.optInt("room_status")!=2)throw new IOException("直播间已离线");JSONObject info=detail.optJSONObject("match_info");if(match.id.startsWith("match:")&&(info==null||!titleMatches(match.label(),info)))throw new IOException("该房间当前已切换其他赛事");if(match.id.startsWith("room:")&&!match.title.equals(detail.optString("room_title")))throw new IOException("该直播间标题已变化，请刷新列表");boolean allowed=false;JSONArray qualities=detail.optJSONArray("play_flow");if(qualities!=null)for(int i=0;i<qualities.length();i++){JSONObject quality=qualities.getJSONObject(i);if(ids[2].equals(quality.optString("code_id"))&&free(quality))allowed=true;}if(!allowed)throw new IOException("该清晰度当前需要登录或不可用，已跳过");Map<String,String> form=new TreeMap<String,String>();form.put("room_id",ids[1]);form.put("code_id",ids[2]);form.put("time",String.valueOf(System.currentTimeMillis()/1000));form.put("signature",signature(form));StringBuilder encoded=new StringBuilder();for(Map.Entry<String,String> item:form.entrySet()){if(encoded.length()>0)encoded.append('&');encoded.append(URLEncoder.encode(item.getKey(),"UTF-8")).append('=').append(URLEncoder.encode(item.getValue(),"UTF-8"));}Object body=post(site,encoded.toString());if(body instanceof String){Cipher cipher=Cipher.getInstance("AES/CBC/PKCS5Padding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(KEY.getBytes("UTF-8"),"AES"),new IvParameterSpec(IV.getBytes("UTF-8")));body=new JSONObject(new String(cipher.doFinal(HttpData.decode64Bytes((String)body)),"UTF-8"));}JSONObject root=(JSONObject)body;if(root.optInt("code")!=200)throw new IOException(root.optString("message","线路暂不可用"));String url=root.getJSONObject("data").optString("play_url");if(!StreamResolver.direct(url))throw new IOException("未提供可播放视频");return url;}
 static Object post(String[] site,String form)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(site[4]+"/v230/play/url").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(6000);c.setReadTimeout(6000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded;charset=UTF-8");c.setRequestProperty("User-Agent",Feeds.UA);c.setRequestProperty("Referer",site[2]+"/");c.setRequestProperty("device","3");c.setRequestProperty("device2","3");c.setRequestProperty("platform",site[0]);c.setRequestProperty("version","1.9.7");c.setRequestProperty("api-version","8");c.setRequestProperty("imei",SESSION);try{byte[] request=form.getBytes("UTF-8");c.setFixedLengthStreamingMode(request.length);try(OutputStream out=c.getOutputStream()){out.write(request);}if(c.getResponseCode()!=200)throw new IOException("播放接口 HTTP "+c.getResponseCode());InputStream in=c.getInputStream();if("gzip".equals(c.getContentEncoding()))in=new GZIPInputStream(in);long deadline=System.nanoTime()+12000000000L;try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] chunk=new byte[4096];int n;while((n=stream.read(chunk))!=-1){if(System.nanoTime()>deadline)throw new SocketTimeoutException("播放响应超时");if(out.size()+n>262144)throw new IOException("播放响应过大");out.write(chunk,0,n);}return new JSONTokener(new String(out.toByteArray(),"UTF-8")).nextValue();}}finally{c.disconnect();}}
}
